/// The stock's documented edge print for this gauge, or null.
inline const EdgeSet* edge_set_for(const char* stock, const char* format) {
    if (!stock || !format) return nullptr;
    for (int i = 0; i < kEdgeSetCount; ++i) {
        const EdgeSet& s = kEdgeSets[i];
        if (s.stock[0] != stock[0]) continue;
        bool same = true;
        for (int k = 0; k < 32; ++k) {
            if (s.stock[k] != stock[k]) { same = false; break; }
            if (s.stock[k] == 0) break;
        }
        if (!same) continue;
        for (int k = 0; k < 16; ++k) {
            if (s.format[k] != format[k]) { same = false; break; }
            if (s.format[k] == 0) break;
        }
        if (same) return &s;
    }
    return nullptr;
}

